<?php
/** По делу v1.8.0. Проверка минут, дат, режимов и локальных маршрутов. */
namespace Markitan\Podelu;
final class Validation {
 public const ROUTES=['/'=>'clients','/clients/'=>'clients','/clients/index.php'=>'clients','/clients/detail.php'=>'detail','/clients/new.php'=>'clientform','/clients/package.php'=>'packageform','/clients/period.php'=>'periodform','/works/'=>'works','/works/index.php'=>'works','/works/work.php'=>'workform','/works/task.php'=>'taskform','/works/entry.php'=>'timeform','/settings/'=>'settings','/settings/index.php'=>'settings','/settings/direction.php'=>'directionform','/settings/template.php'=>'presetform'];
 public static function text($v,int $max,bool $required=false): string {if(!is_string($v))throw new \InvalidArgumentException('Некорректный текст.');$v=trim($v);if(($required&&$v==='')||mb_strlen($v)>$max||preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u',$v))throw new \InvalidArgumentException('Проверьте обязательные поля и длину текста.');return $v;}
 public static function id($v,bool $zero=false): int {if(!is_scalar($v)||!preg_match('/^\d{1,10}$/',(string)$v))throw new \InvalidArgumentException('Некорректное число.');$n=(int)$v;if($n<($zero?0:1)||$n>2147483647)throw new \InvalidArgumentException('Некорректный ID.');return $n;}
 public static function month($v,bool $empty=false): string {if($empty&&$v==='')return '';if(!is_string($v)||!preg_match('/^(20\d{2}|2100)-(0[1-9]|1[0-2])$/',$v))throw new \InvalidArgumentException('Выберите месяц.');return $v;}
 public static function date($v): string {if(!is_string($v)||!preg_match('/^(20\d{2}|2100)-(\d{2})-(\d{2})$/',$v,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))throw new \InvalidArgumentException('Некорректная дата.');return $v;}
 public static function parts($h,$m): int {$h=self::id($h,true);$m=self::id($m,true);$n=$h*60+$m;if($h>24||$m>59||$n<1||$n>1440)throw new \InvalidArgumentException('Укажите от 1 минуты до 24 часов; минуты 0–59.');return $n;}
 public static function limit($v): int {if(!is_string($v)&&!is_numeric($v))throw new \InvalidArgumentException('Укажите лимит.');$v=str_replace(',','.',trim((string)$v));if(!preg_match('/^(\d{1,5})(?:\.(\d{1,2}))?$/',$v,$m))throw new \InvalidArgumentException('Лимит часов: шаг 0,25.');$f=isset($m[2])?(int)str_pad($m[2],2,'0'):0;if(!in_array($f,[0,25,50,75],true))throw new \InvalidArgumentException('Лимит часов: шаг 0,25.');return (int)$m[1]*60+intdiv($f*60,100);}
 public static function durations($v): array {$s=self::text($v,128,true);$a=[];foreach(preg_split('/[,;\s]+/u',$s,-1,PREG_SPLIT_NO_EMPTY) as $p){$n=self::id($p);if($n>1440)throw new \InvalidArgumentException('Длительность до 1440 минут.');$a[]=$n;}$a=array_values(array_unique($a));if(count($a)<1||count($a)>6)throw new \InvalidArgumentException('Укажите 1–6 длительностей.');return $a;}
 public static function choice($v,array $a): string {if(!is_string($v)||!in_array($v,$a,true))throw new \InvalidArgumentException('Некорректный режим.');return $v;}
 public static function token($v): string {if(!is_string($v)||!preg_match('/^[a-f0-9]{32}$/',$v))throw new \InvalidArgumentException('Обновите форму.');return $v;}
 public static function local($v): string {if(!is_string($v)||strlen($v)>6000||preg_match('/[\x00-\x20\x7F\\\\]/',$v)||substr($v,0,1)!=='/'||substr($v,0,2)==='//')return '/clients/';$p=parse_url($v);if(!$p||isset($p['host'])||isset($p['scheme'])||!isset(self::ROUTES[$p['path']??'']))return '/clients/';return $v;}
 public static function workUrl(int $c,string $m,string $context): string {$p=parse_url(self::local($context));$q=[];parse_str($p['query']??'',$q);if(($p['path']??'')==='/clients/detail.php'&&is_scalar($q['client']??null)&&(int)$q['client']===$c)return '/clients/detail.php?'.http_build_query(['client'=>$c,'month'=>$m,'tab'=>'works']);return '/works/?'.http_build_query(['client'=>$c,'month'=>$m]);}
 public static function duration(int $n): string {$n=abs($n);$h=intdiv($n,60);$m=$n%60;return ($h?$h.' ч':'').($h&&$m?' ':'').($m||!$h?$m.' мин':'');}
}
